CREATE OR REPLACE FUNCTION planit_private.can_delete_avatar_upload(p_path text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
    if auth.uid() is null or split_part(p_path,'/',1) <> auth.uid()::text then return false; end if;
    if current_setting('transaction_isolation') <> 'read committed' then
        raise exception 'retry_read_committed' using errcode = '40001';
    end if;
    perform pg_advisory_xact_lock(hashtextextended('avatars/' || p_path,0));
    return not exists (select 1 from public.files where bucket_name = 'avatars' and storage_path = p_path);
end;
$function$

CREATE OR REPLACE FUNCTION planit_private.can_delete_event_upload(p_path text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
    if auth.uid() is null or split_part(p_path,'/',1) <> auth.uid()::text then return false; end if;
    if current_setting('transaction_isolation') <> 'read committed' then
        raise exception 'read_committed_required' using errcode = '25000';
    end if;
    perform pg_advisory_xact_lock(hashtextextended('event_media/' || p_path,0));
    return not exists(select 1 from public.files where bucket_name = 'event_media' and storage_path = p_path);
end;
$function$

CREATE OR REPLACE FUNCTION planit_private.handle_new_auth_user()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
    v_display_name text;
    v_username text;
    v_attempt integer;
begin
    v_display_name := btrim(coalesce(new.raw_user_meta_data ->> 'display_name', ''));
    if char_length(v_display_name) not between 2 and 60 then
        raise exception 'display_name must contain between 2 and 60 characters'
            using errcode = '23514';
    end if;

    for v_attempt in 1..5 loop
        v_username := 'user_' || substr(replace(gen_random_uuid()::text, '-', ''), 1, 12);
        begin
            insert into public.profiles (id, username, display_name)
            values (new.id, v_username, v_display_name);
            return new;
        exception when unique_violation then
            -- Reintentar sólo una colisión del username generado.
            if exists (select 1 from public.profiles where id = new.id) then
                raise;
            end if;
        end;
    end loop;

    raise exception 'could not generate a unique username after five attempts';
end;
$function$

CREATE OR REPLACE FUNCTION planit_private.lock_gallery(p_event_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
    if auth.uid() is null then raise exception 'authentication_required' using errcode = '42501'; end if;
    if current_setting('transaction_isolation') <> 'read committed' then
        raise exception 'read_committed_required' using errcode = '25000';
    end if;
    perform 1 from public.events where id = p_event_id and organizer_id = auth.uid() for update;
    if not found then raise exception 'not_event_organizer' using errcode = '42501'; end if;
end;
$function$

CREATE OR REPLACE FUNCTION planit_private.lock_social_pair(p_target_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_count integer;
begin
    if auth.uid() is null then raise exception 'authentication_required' using errcode = '42501'; end if;
    if current_setting('transaction_isolation') <> 'read committed' then
        raise exception 'retry_read_committed' using errcode = '40001';
    end if;
    if p_target_id is null or p_target_id = auth.uid() then
        raise exception 'invalid_social_target' using errcode = '22023';
    end if;
    perform 1 from public.profiles where id in (auth.uid(), p_target_id)
        order by id for no key update;
    get diagnostics v_count = row_count;
    if v_count <> 2 then raise exception 'profile_unavailable' using errcode = '42501'; end if;
end;
$function$

CREATE OR REPLACE FUNCTION planit_private.protect_event_visibility()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
    if old.visibility = new.visibility then return new; end if;
    if auth.uid() is null or old.organizer_id <> auth.uid() then
        raise exception 'event_unavailable' using errcode = '42501';
    end if;
    if current_setting('transaction_isolation') <> 'read committed' then
        raise exception 'retry_read_committed' using errcode = '40001';
    end if;
    -- UPDATE already holds event lock. Same event -> participation -> grant order.
    if new.visibility = 'unlisted' then
        perform 1 from public.event_participations where event_id = new.id and status = 'confirmed' order by id for update;
        if exists (select 1 from public.event_participations p join public.event_access_grants g
            on g.event_id = p.event_id and g.user_id = p.user_id
            where p.event_id = new.id and p.status = 'confirmed' and g.status = 'revoked') then
            raise exception 'confirmed_access_revoked' using errcode = 'P0001';
        end if;
        insert into public.event_access_grants(event_id,user_id)
            select new.id,p.user_id from public.event_participations p where p.event_id = new.id and p.status = 'confirmed'
            on conflict (event_id,user_id) do nothing;
    else
        -- D12: invalidate only links, never individual grants or participation.
        update public.event_access_links set revoked_at = clock_timestamp() at time zone 'America/Argentina/Buenos_Aires'
            where event_id = new.id and revoked_at is null;
    end if;
    return new;
end;
$function$

CREATE OR REPLACE FUNCTION planit_private.stamp_notification_read()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
    new.read_at := coalesce(old.read_at, clock_timestamp() at time zone 'America/Argentina/Buenos_Aires');
    return new;
end;
$function$

CREATE OR REPLACE FUNCTION planit_private.touch_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
    new.updated_at := clock_timestamp() at time zone 'America/Argentina/Buenos_Aires';
    return new;
end;
$function$

CREATE OR REPLACE FUNCTION planit_private.validate_event_file()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
    if current_setting('transaction_isolation') <> 'read committed' then
        raise exception 'read_committed_required' using errcode = '25000';
    end if;
    perform pg_advisory_xact_lock(hashtextextended(new.bucket_name || '/' || new.storage_path,0));
    if not exists(select 1 from storage.objects where bucket_id = new.bucket_name and name = new.storage_path
        and owner_id = auth.uid()::text and metadata ->> 'mimetype' = new.mime_type
        and (metadata ->> 'size')::bigint = new.size_bytes
        and (new.bucket_name <> 'avatars' or metadata ->> 'cacheControl' in ('no-store','no-cache','max-age=0'))) then
        raise exception 'invalid_image' using errcode = 'P0001';
    end if;
    return new;
end;
$function$

CREATE OR REPLACE FUNCTION planit_private.validate_event_image()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
    perform planit_private.lock_gallery(new.event_id);
    if not exists (select 1 from public.files where id = new.file_id
        and uploaded_by = auth.uid() and bucket_name = 'event_media') then
        raise exception 'invalid_image_owner' using errcode = '42501';
    end if;
    return new;
end;
$function$

CREATE OR REPLACE FUNCTION planit_private.validate_new_event()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
    if new.starts_at <= (clock_timestamp() at time zone 'America/Argentina/Buenos_Aires') then
        raise exception 'start_not_future' using errcode = 'P0001';
    end if;
    if not exists (select 1 from public.categories where id = new.category_id and is_active) then
        raise exception 'category_inactive' using errcode = 'P0001';
    end if;
    return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.add_event_image(p_event_id uuid, p_storage_path text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_file uuid; v_image uuid; v_mime text; v_size bigint; v_slot integer;
begin
    perform planit_private.lock_gallery(p_event_id);
    if p_storage_path is null or split_part(p_storage_path, '/', 1) <> auth.uid()::text
        or split_part(p_storage_path, '/', 2) <> p_event_id::text then
        raise exception 'invalid_image' using errcode = 'P0001';
    end if;
    -- Path is the idempotency key: reconcile a lost commit before checking slots.
    select i.id into v_image from public.event_images i join public.files f on f.id = i.file_id
        where i.event_id = p_event_id and f.bucket_name = 'event_media' and f.storage_path = p_storage_path;
    if found then return v_image; end if;
    select s into v_slot from generate_series(0,9) s where not exists
        (select 1 from public.event_images where event_id = p_event_id and sort_order = s) order by s limit 1;
    if v_slot is null then raise exception 'gallery_full' using errcode = 'P0001'; end if;
    perform pg_advisory_xact_lock(hashtextextended('event_media/' || p_storage_path,0));
    select metadata ->> 'mimetype', (metadata ->> 'size')::bigint into v_mime,v_size
        from storage.objects where bucket_id = 'event_media' and name = p_storage_path
        and owner_id = auth.uid()::text for update;
    if not found then raise exception 'invalid_image' using errcode = 'P0001'; end if;
    select id into v_file from public.files where bucket_name = 'event_media' and storage_path = p_storage_path;
    if v_file is null then
        insert into public.files(uploaded_by,bucket_name,storage_path,mime_type,size_bytes)
            values(auth.uid(),'event_media',p_storage_path,v_mime,v_size) returning id into v_file;
    end if;
    insert into public.event_images(event_id,file_id,sort_order) values(p_event_id,v_file,v_slot) returning id into v_image;
    return v_image;
end;
$function$

CREATE OR REPLACE FUNCTION public.archive_event(p_event_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
    v_event public.events%rowtype;
    v_now timestamp;
begin
    if auth.uid() is null then raise exception 'authentication_required' using errcode = '42501'; end if;
    if current_setting('transaction_isolation') <> 'read committed' then
        raise exception 'retry_read_committed' using errcode = '40001';
    end if;
    select * into v_event from public.events where id = p_event_id for update;
    if not found or v_event.organizer_id <> auth.uid() then
        raise exception 'event_unavailable' using errcode = '42501';
    end if;
    if v_event.archived_at is not null then return v_event.id; end if;
    v_now := clock_timestamp() at time zone 'America/Argentina/Buenos_Aires';
    -- Cancellation precedes archive in this transaction. Any later failure rolls
    -- both writes back; registrations and chat share this event-row lock.
    if v_event.cancelled_at is null and v_event.ends_at > v_now then
        update public.events set cancelled_at = v_now where id = v_event.id;
    end if;
    update public.events set archived_at = v_now where id = v_event.id;
    return v_event.id;
end;
$function$

CREATE OR REPLACE FUNCTION public.cancel_event(p_event_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
    v_event public.events%rowtype;
begin
    if auth.uid() is null then raise exception 'authentication_required' using errcode = '42501'; end if;
    if current_setting('transaction_isolation') <> 'read committed' then
        raise exception 'retry_read_committed' using errcode = '40001';
    end if;
    select * into v_event from public.events where id = p_event_id for update;
    if not found or v_event.organizer_id <> auth.uid() then
        raise exception 'event_unavailable' using errcode = '42501';
    end if;
    if v_event.archived_at is not null then raise exception 'event_archived' using errcode = 'P0001'; end if;
    if v_event.cancelled_at is not null then return v_event.id; end if;
    if v_event.ends_at <= (clock_timestamp() at time zone 'America/Argentina/Buenos_Aires') then
        raise exception 'event_ended' using errcode = 'P0001';
    end if;
    update public.events set cancelled_at = (clock_timestamp() at time zone 'America/Argentina/Buenos_Aires')
        where id = v_event.id;
    return v_event.id;
end;
$function$

CREATE OR REPLACE FUNCTION public.create_event(p_id uuid, p_title text, p_description text, p_starts_at timestamp without time zone, p_ends_at timestamp without time zone, p_category_id uuid, p_capacity integer, p_address text, p_latitude double precision, p_longitude double precision, p_location_name text DEFAULT NULL::text, p_image_paths text[] DEFAULT '{}'::text[], p_visibility text DEFAULT 'public'::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
    v_event_id uuid;
    v_file_id uuid;
    v_path text;
    v_mime text;
    v_size bigint;
    v_sort integer := 0;
begin
    if (select auth.uid()) is null then raise exception 'authentication_required' using errcode = '42501'; end if;
    if p_visibility is null or p_visibility not in ('public','unlisted') then raise exception 'invalid_visibility' using errcode = '23514'; end if;
    if p_id is null then raise exception 'request_id_required' using errcode = '23514'; end if;
    -- Serialize retries for one publication; a lost response must not duplicate it.
    perform pg_advisory_xact_lock(hashtextextended(p_id::text, 0));
    if exists (select 1 from public.events where id = p_id and organizer_id = (select auth.uid())) then return p_id; end if;
    if p_image_paths is null or cardinality(p_image_paths) > 10 then
        raise exception 'invalid_image_count' using errcode = '23514';
    end if;
    insert into public.events (id, category_id, title, description, starts_at, ends_at, location_name, address, latitude, longitude, capacity, visibility)
    values (p_id, p_category_id, btrim(p_title), btrim(p_description), p_starts_at, p_ends_at, nullif(btrim(p_location_name), ''), btrim(p_address), p_latitude, p_longitude, p_capacity, p_visibility)
    returning id into v_event_id;
    foreach v_path in array p_image_paths loop
        select metadata ->> 'mimetype', (metadata ->> 'size')::bigint into v_mime, v_size
        from storage.objects where bucket_id = 'event_media' and name = v_path
            and owner_id = (select auth.uid())::text;
        if not found or v_path is null or split_part(v_path, '/', 1) <> (select auth.uid())::text then
            raise exception 'invalid_image' using errcode = 'P0001';
        end if;
        insert into public.files (bucket_name, storage_path, mime_type, size_bytes)
        values ('event_media', v_path, v_mime, v_size) returning id into v_file_id;
        insert into public.event_images (event_id, file_id, sort_order) values (v_event_id, v_file_id, v_sort);
        v_sort := v_sort + 1;
    end loop;
    return v_event_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.create_or_rotate_event_link(p_event_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_event public.events%rowtype; v_token text; v_now timestamp;
begin
    if auth.uid() is null then raise exception 'authentication_required' using errcode = '42501'; end if;
    if current_setting('transaction_isolation') <> 'read committed' then raise exception 'retry_read_committed' using errcode = '40001'; end if;
    select * into v_event from public.events where id = p_event_id for update;
    if not found or v_event.organizer_id <> auth.uid() then raise exception 'event_unavailable' using errcode = '42501'; end if;
    v_now := clock_timestamp() at time zone 'America/Argentina/Buenos_Aires';
    if v_event.visibility <> 'unlisted' then raise exception 'event_not_unlisted' using errcode = 'P0001'; end if;
    if v_event.ends_at <= v_now or v_event.cancelled_at is not null or v_event.archived_at is not null then
        raise exception 'event_link_closed' using errcode = 'P0001';
    end if;
    v_token := encode(extensions.gen_random_bytes(32), 'hex');
    update public.event_access_links set revoked_at = v_now where event_id = p_event_id and revoked_at is null;
    insert into public.event_access_links(event_id,created_by,token_hash,created_at)
        values(p_event_id,auth.uid(),encode(extensions.digest(v_token,'sha256'),'hex'),v_now);
    return v_token;
end;
$function$

CREATE OR REPLACE FUNCTION public.follow_user(p_target_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_visibility text; v_status text; v_follow public.user_follows%rowtype; v_now timestamp;
begin
    perform planit_private.lock_social_pair(p_target_id);
    if planit_private.social_blocked(p_target_id) then
        raise exception 'profile_unavailable' using errcode = '42501';
    end if;
    select * into v_follow from public.user_follows
        where follower_id = auth.uid() and followed_id = p_target_id;
    if found and v_follow.status in ('pending', 'accepted') then
        return jsonb_build_object('status', v_follow.status, 'request_version', v_follow.request_version);
    end if;
    select visibility into v_visibility from public.profiles where id = p_target_id;
    v_status := case when v_visibility = 'public' then 'accepted' else 'pending' end;
    v_now := clock_timestamp() at time zone 'America/Argentina/Buenos_Aires';
    insert into public.user_follows(follower_id, followed_id, status, requested_at, responded_at)
    values (auth.uid(), p_target_id, v_status, v_now, case when v_status = 'accepted' then v_now end)
    on conflict (follower_id, followed_id) do update set status = excluded.status,
        request_version = gen_random_uuid(), requested_at = excluded.requested_at,
        responded_at = excluded.responded_at returning * into v_follow;
    return jsonb_build_object('status', v_follow.status, 'request_version', v_follow.request_version);
end;
$function$

CREATE OR REPLACE FUNCTION public.get_direct_messages(p_conversation_id uuid, p_before_at timestamp without time zone DEFAULT NULL::timestamp without time zone, p_before_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 30)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare v_rows jsonb; v_more boolean;
begin
    if auth.uid() is null or not exists (select 1 from public.conversations c
        where c.id = p_conversation_id and c.kind = 'direct') then
        raise exception 'conversation_unavailable' using errcode = '42501';
    end if;
    if p_limit is null or p_limit not between 1 and 50 or (p_before_at is null) <> (p_before_id is null) then
        raise exception 'invalid_message_cursor' using errcode = '22023';
    end if;
    with page as (
        select m.id, m.sender_id, m.body, m.created_at from public.messages m
        where m.conversation_id = p_conversation_id
            and (p_before_at is null or (m.created_at,m.id) < (p_before_at,p_before_id))
        order by m.created_at desc, m.id desc limit p_limit + 1
    ), numbered as (select *, row_number() over(order by created_at desc,id desc) as n from page)
    select coalesce(jsonb_agg(to_jsonb(numbered) - 'n' order by created_at desc,id desc)
        filter(where n <= p_limit), '[]'::jsonb), count(*) > p_limit into v_rows,v_more from numbered;
    return jsonb_build_object('messages',v_rows,'next_cursor',case when v_more then
        jsonb_build_object('created_at',v_rows->(p_limit-1)->'created_at','id',v_rows->(p_limit-1)->'id') end);
end;
$function$

CREATE OR REPLACE FUNCTION public.get_event_access_grants(p_event_id uuid, p_status text DEFAULT 'active'::text, p_after_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 30)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
    v_event public.events%rowtype;
    v_rows jsonb;
    v_more boolean;
begin
    if auth.uid() is null then raise exception 'access_denied' using errcode = '42501'; end if;
    select * into v_event from public.events where id = p_event_id;
    if not found or v_event.organizer_id <> auth.uid() then
        raise exception 'access_denied' using errcode = '42501';
    end if;
    if v_event.visibility <> 'unlisted' then raise exception 'event_not_hidden'; end if;
    if p_status is null or p_status not in ('active', 'revoked') or p_limit is null or p_limit < 1 or p_limit > 50 then
        raise exception 'invalid_access_query' using errcode = '22023';
    end if;
    with candidates as (
        select g.id, g.user_id, g.status, case when planit_private.social_blocked(p.id) then '' else p.username end as username,
            case when planit_private.social_blocked(p.id) then 'Perfil no disponible' else p.display_name end as display_name,
            exists(select 1 from public.event_participations ep
                where ep.event_id = g.event_id and ep.user_id = g.user_id and ep.status = 'confirmed') as is_confirmed
        from public.event_access_grants g join public.profiles p on p.id = g.user_id
        where g.event_id = p_event_id and g.status = p_status and (p_after_id is null or g.id > p_after_id)
        order by g.id limit p_limit + 1
    ), numbered as (select *, row_number() over(order by id) as n from candidates)
    select coalesce(jsonb_agg(jsonb_build_object('id',id,'user_id',user_id,'status',status,
        'username',username,'display_name',display_name,'avatar_url',null,'is_confirmed',is_confirmed)
        order by id) filter(where n <= p_limit),'[]'::jsonb), count(*) > p_limit
    into v_rows, v_more from numbered;
    return jsonb_build_object('title',v_event.title,'event_state',
        case when v_event.archived_at is not null then 'archived' when v_event.cancelled_at is not null then 'cancelled'
            when v_event.ends_at <= clock_timestamp() at time zone 'America/Argentina/Buenos_Aires' then 'ended' else 'open' end,
        'grants',v_rows,'next_cursor',case when v_more then v_rows->(p_limit-1)->>'id' else null end);
end;
$function$

CREATE OR REPLACE FUNCTION public.get_event_duplicate_source(p_event_id uuid)
 RETURNS TABLE(title text, description text, category_id uuid, location_name text, address text, latitude double precision, longitude double precision, capacity integer)
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
begin
    if auth.uid() is null then raise exception 'authentication_required' using errcode = '42501'; end if;
    return query select e.title, e.description, e.category_id, e.location_name,
        e.address, e.latitude, e.longitude, e.capacity
        from public.events e where e.id = p_event_id and e.organizer_id = auth.uid();
    if not found then raise exception 'event_unavailable' using errcode = '42501'; end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.get_event_link_status(p_event_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
    if auth.uid() is null or not exists(select 1 from public.events where id = p_event_id and organizer_id = auth.uid()) then
        raise exception 'event_unavailable' using errcode = '42501';
    end if;
    return exists(select 1 from public.event_access_links where event_id = p_event_id and revoked_at is null);
end;
$function$

CREATE OR REPLACE FUNCTION public.get_event_rejoin_resolution(p_event_id uuid, p_request_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_status text;
begin
    if auth.uid() is null then raise exception 'authentication_required' using errcode = '42501'; end if;
    if not exists (select 1 from public.events where id=p_event_id and organizer_id=auth.uid()) then raise exception 'event_unavailable' using errcode='42501'; end if;
    select r.status into v_status from public.event_rejoin_requests r join public.event_participations p on p.id=r.participation_id where r.id=p_request_id and p.event_id=p_event_id;
    if not found then raise exception 'rejoin_unavailable' using errcode='P0001'; end if;
    return v_status;
end;
$function$

CREATE OR REPLACE FUNCTION public.get_event_social_participants(p_event_id uuid, p_after_user_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 30)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_rows jsonb; v_more boolean;
begin
    -- Exact R4 detail + R3 confirmed boundary; this does not grant administration.
    if not planit_private.can_read_event_chat(p_event_id) then
        raise exception 'participants_unavailable' using errcode = '42501';
    end if;
    if p_limit is null or p_limit not between 1 and 50 then
        raise exception 'invalid_social_query' using errcode = '22023';
    end if;
    with page as (
        select p.id as user_id, p.display_name, p.username,
            case when p.avatar_file_id is not null then p.id end as avatar
        from public.event_participations ep join public.profiles p on p.id = ep.user_id
        where ep.event_id = p_event_id and ep.status = 'confirmed'
            and not planit_private.social_blocked(p.id)
            and (p_after_user_id is null or p.id > p_after_user_id)
        order by p.id limit p_limit + 1
    ), numbered as (select *, row_number() over(order by user_id) as n from page)
    select coalesce(jsonb_agg(to_jsonb(numbered) - 'n' order by user_id)
        filter(where n <= p_limit), '[]'::jsonb), count(*) > p_limit into v_rows, v_more from numbered;
    return jsonb_build_object('participants', v_rows,
        'next_cursor', case when v_more then v_rows->(p_limit-1)->>'user_id' end);
end;
$function$

CREATE OR REPLACE FUNCTION public.get_my_rejoin_status(p_event_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
    v_event public.events%rowtype;
    v_part public.event_participations%rowtype;
    v_request public.event_rejoin_requests%rowtype;
    v_next timestamp;
    v_now timestamp := statement_timestamp() at time zone 'America/Argentina/Buenos_Aires';
begin
    if auth.uid() is null then raise exception 'authentication_required' using errcode = '42501'; end if;
    select * into v_event from public.events where id = p_event_id;
    select * into v_part from public.event_participations where event_id = p_event_id and user_id = auth.uid();
    if not planit_private.can_view_event(p_event_id) then
        raise exception 'event_unavailable' using errcode = '42501';
    end if;
    select * into v_request from public.event_rejoin_requests where participation_id = v_part.id order by requested_at desc, id desc limit 1;
    if v_request.status = 'rejected' then v_next := v_request.resolved_at + interval '7 days'; end if;
    return jsonb_build_object('request_id', v_request.id, 'status', v_request.status,
        'requested_at', v_request.requested_at, 'resolved_at', v_request.resolved_at, 'next_eligible_at', v_next,
        'can_request', coalesce(v_part.status = 'removed' and v_event.organizer_id <> auth.uid()
            and v_event.cancelled_at is null and v_event.archived_at is null and v_event.ends_at > v_now
            and v_request.status is distinct from 'pending' and (v_next is null or v_next <= v_now), false));
end;
$function$

CREATE OR REPLACE FUNCTION public.get_notification_changes(p_ids uuid[])
 RETURNS TABLE(id uuid, type text, title text, body text, read_at timestamp without time zone, created_at timestamp without time zone, target text)
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
begin
    if auth.uid() is null then raise exception 'authentication_required' using errcode = '42501'; end if;
    if p_ids is null or cardinality(p_ids) > 100 then raise exception 'invalid_ids' using errcode = '22023'; end if;
    return query select n.id, n.type, n.title, n.body, n.read_at, n.created_at, public.get_notification_target(n.id)
        from public.notifications n where n.id = any(p_ids) and n.recipient_id = (select auth.uid())
        order by n.created_at desc, n.id desc;
end;
$function$

CREATE OR REPLACE FUNCTION public.get_notifications(p_before_at timestamp without time zone DEFAULT NULL::timestamp without time zone, p_before_id uuid DEFAULT NULL::uuid)
 RETURNS TABLE(id uuid, type text, title text, body text, read_at timestamp without time zone, created_at timestamp without time zone, target text)
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
begin
    if auth.uid() is null then raise exception 'authentication_required' using errcode = '42501'; end if;
    if (p_before_at is null) <> (p_before_id is null) then raise exception 'invalid_cursor' using errcode = '22023'; end if;
    return query select n.id, n.type, n.title, n.body, n.read_at, n.created_at, public.get_notification_target(n.id)
        from public.notifications n where n.recipient_id = (select auth.uid())
        and (p_before_at is null or (n.created_at, n.id) < (p_before_at, p_before_id))
        order by n.created_at desc, n.id desc limit 31;
end;
$function$

CREATE OR REPLACE FUNCTION public.get_or_create_direct_conversation(p_target_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_id uuid;
begin
    perform planit_private.lock_social_pair(p_target_id);
    if planit_private.social_blocked(p_target_id) then
        raise exception 'profile_unavailable' using errcode = '42501';
    end if;
    select id into v_id from public.conversations where kind = 'direct'
        and user_low_id = least(auth.uid(), p_target_id) and user_high_id = greatest(auth.uid(), p_target_id);
    if found then return v_id; end if;
    insert into public.conversations(kind, user_low_id, user_high_id)
        values ('direct', least(auth.uid(), p_target_id), greatest(auth.uid(), p_target_id))
        returning id into v_id;
    return v_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.get_social_counts(p_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
    if not planit_private.can_read_social_content(p_user_id) then
        raise exception 'profile_unavailable' using errcode = '42501';
    end if;
    return (
        select jsonb_build_object('followers', count(*) filter(where followed_id = p_user_id),
            'following', count(*) filter(where follower_id = p_user_id))
        from public.user_follows f where status = 'accepted' and p_user_id in (follower_id,followed_id)
            and not planit_private.social_blocked(case when follower_id = p_user_id then followed_id else follower_id end)
            and not exists (select 1 from public.user_blocks b where
                (b.blocker_id = f.follower_id and b.blocked_id = f.followed_id) or
                (b.blocker_id = f.followed_id and b.blocked_id = f.follower_id))
    );
end;
$function$

CREATE OR REPLACE FUNCTION public.get_social_profile(p_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_profile public.profiles%rowtype; v_result jsonb;
begin
    if auth.uid() is null then raise exception 'authentication_required' using errcode = '42501'; end if;
    if planit_private.social_blocked(p_user_id) then return jsonb_build_object('unavailable', true); end if;
    select * into v_profile from public.profiles where id = p_user_id;
    if not found then return jsonb_build_object('unavailable', true); end if;
    v_result := jsonb_build_object('display_name', v_profile.display_name, 'username', v_profile.username,
        'avatar', case when v_profile.avatar_file_id is not null then p_user_id else null end);
    if p_user_id = auth.uid() or v_profile.visibility = 'public' or exists (
        select 1 from public.user_follows where follower_id = auth.uid() and followed_id = p_user_id and status = 'accepted'
    ) then v_result := v_result || jsonb_build_object('bio', v_profile.bio); end if;
    return v_result;
end;
$function$

CREATE OR REPLACE FUNCTION public.get_social_profile_events(p_user_id uuid, p_before_starts_at timestamp without time zone DEFAULT NULL::timestamp without time zone, p_before_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 30)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_rows jsonb; v_more boolean;
begin
    if auth.uid() is null then raise exception 'authentication_required' using errcode = '42501'; end if;
    if not planit_private.can_read_social_content(p_user_id) then
        raise exception 'profile_unavailable' using errcode = '42501';
    end if;
    if p_limit is null or p_limit not between 1 and 50 or
        (p_before_starts_at is null) <> (p_before_id is null) then
        raise exception 'invalid_social_query' using errcode = '22023';
    end if;
    with page as (
        select e.id, e.title, e.starts_at, e.ends_at, e.category_id, e.location_name
        from public.events e where e.organizer_id = p_user_id and e.visibility = 'public'
            and e.cancelled_at is null and e.archived_at is null
            and e.ends_at > statement_timestamp() at time zone 'America/Argentina/Buenos_Aires'
            and (p_before_starts_at is null or (e.starts_at, e.id) < (p_before_starts_at, p_before_id))
        order by e.starts_at desc, e.id desc limit p_limit + 1
    ), numbered as (select *, row_number() over(order by starts_at desc, id desc) as n from page)
    select coalesce(jsonb_agg(to_jsonb(numbered) - 'n' order by starts_at desc, id desc)
        filter(where n <= p_limit), '[]'::jsonb), count(*) > p_limit into v_rows, v_more from numbered;
    return jsonb_build_object('events', v_rows, 'next_cursor', case when v_more then
        jsonb_build_object('starts_at', v_rows->(p_limit-1)->'starts_at', 'id', v_rows->(p_limit-1)->'id') end);
end;
$function$

CREATE OR REPLACE FUNCTION public.get_social_relationship(p_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
    if auth.uid() is null then raise exception 'authentication_required' using errcode = '42501'; end if;
    if planit_private.social_blocked(p_user_id) then
        return jsonb_build_object('unavailable', true, 'blocked_by_me', exists (
            select 1 from public.user_blocks where blocker_id = auth.uid() and blocked_id = p_user_id));
    end if;
    if not exists (select 1 from public.profiles where id = p_user_id) then
        return jsonb_build_object('unavailable', true, 'blocked_by_me', false);
    end if;
    return jsonb_build_object('visibility', (select visibility from public.profiles where id = p_user_id),
        'follow', (select jsonb_build_object('status',status,'request_version',request_version)
            from public.user_follows where follower_id = auth.uid() and followed_id = p_user_id));
end;
$function$

CREATE OR REPLACE FUNCTION public.leave_event(p_event_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_user uuid := auth.uid();
begin
    if v_user is null then raise exception 'authentication_required' using errcode = '42501'; end if;
    if current_setting('transaction_isolation') <> 'read committed' then
        raise exception 'retry_read_committed' using errcode = '40001';
    end if;
    perform 1 from public.events where id = p_event_id for update;
    if not found or not planit_private.can_view_event(p_event_id) then
        raise exception 'event_unavailable' using errcode = '42501';
    end if;
    if not exists (select 1 from public.event_participations where event_id = p_event_id and user_id = v_user) then
        raise exception 'not_participating' using errcode = 'P0001';
    end if;
    update public.event_participations set status = 'cancelled'
        where event_id = p_event_id and user_id = v_user and status = 'confirmed';
end;
$function$

CREATE OR REPLACE FUNCTION public.mark_notification_read(p_id uuid)
 RETURNS timestamp without time zone
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare v_read_at timestamp;
begin
    if auth.uid() is null then raise exception 'authentication_required' using errcode = '42501'; end if;
    update public.notifications set read_at = clock_timestamp() at time zone 'America/Argentina/Buenos_Aires'
        where id = p_id and recipient_id = (select auth.uid()) returning read_at into v_read_at;
    if not found then raise exception 'notification_unavailable' using errcode = '42501'; end if;
    return v_read_at;
end;
$function$

CREATE OR REPLACE FUNCTION public.redeem_event_link(p_token text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
    v_user uuid := auth.uid();
    v_hash text;
    v_event_id uuid;
    v_event public.events%rowtype;
    v_link_id uuid;
    v_grant public.event_access_grants%rowtype;
    v_now timestamp;
begin
    if v_user is null then raise exception 'authentication_required' using errcode = '42501'; end if;
    if current_setting('transaction_isolation') <> 'read committed' then
        raise exception 'retry_read_committed' using errcode = '40001';
    end if;
    -- One indistinguishable error for malformed, unknown, rotated/revoked links,
    -- closed or public events and revoked users: no event enumeration oracle.
    if p_token is null or p_token !~ '^[0-9a-f]{64}$' then
        raise exception 'invite_unavailable' using errcode = 'P0001';
    end if;
    v_hash := encode(extensions.digest(p_token, 'sha256'), 'hex');
    select l.event_id into v_event_id from public.event_access_links l where l.token_hash = v_hash;
    if v_event_id is null then raise exception 'invite_unavailable' using errcode = 'P0001'; end if;
    -- Event lock first (same as rotate/visibility/closure/register); then re-read
    -- the link so a rotation that won the lock race invalidates this token.
    select * into v_event from public.events where id = v_event_id for update;
    if not found then raise exception 'invite_unavailable' using errcode = 'P0001'; end if;
    select l.id into v_link_id from public.event_access_links l
        where l.token_hash = v_hash and l.event_id = v_event_id and l.revoked_at is null;
    v_now := clock_timestamp() at time zone 'America/Argentina/Buenos_Aires';
    if v_link_id is null or v_event.visibility <> 'unlisted' or v_event.cancelled_at is not null
        or v_event.archived_at is not null or v_event.ends_at <= v_now then
        raise exception 'invite_unavailable' using errcode = 'P0001';
    end if;
    if v_event.organizer_id = v_user then return v_event_id; end if;
    select * into v_grant from public.event_access_grants
        where event_id = v_event_id and user_id = v_user for update;
    if found then
        -- Revoked wins absolutely: no token, old or new, can resurrect it.
        if v_grant.status <> 'active' then raise exception 'invite_unavailable' using errcode = 'P0001'; end if;
        return v_event_id;
    end if;
    insert into public.event_access_grants(event_id, user_id, source_link_id, granted_at, updated_at)
        values (v_event_id, v_user, v_link_id, v_now, v_now)
        on conflict (event_id, user_id) do nothing;
    -- Confirm the committed outcome before reporting success.
    if not exists (select 1 from public.event_access_grants
        where event_id = v_event_id and user_id = v_user and status = 'active') then
        raise exception 'invite_unavailable' using errcode = 'P0001';
    end if;
    return v_event_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.register_for_event(p_event_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
    v_user uuid := auth.uid();
    v_event public.events%rowtype;
    v_status text;
begin
    if v_user is null then raise exception 'authentication_required' using errcode = '42501'; end if;
    -- Counts after a waited lock need a fresh snapshot. Supabase/PostgREST uses
    -- READ COMMITTED; reject frozen snapshots rather than risk oversubscription.
    if current_setting('transaction_isolation') <> 'read committed' then
        raise exception 'retry_read_committed' using errcode = '40001';
    end if;
    -- Always event first, participation second. Subsequent statements see committed
    -- competitors under READ COMMITTED.
    select * into v_event from public.events where id = p_event_id for update;
    if not found then raise exception 'event_unavailable' using errcode = '42501'; end if;
    if v_event.visibility = 'unlisted' and not planit_private.can_view_event(p_event_id) then
        raise exception 'event_unavailable' using errcode = '42501';
    end if;
    if v_event.organizer_id = v_user then raise exception 'organizer_cannot_register' using errcode = 'P0001'; end if;
    if v_event.archived_at is not null or v_event.cancelled_at is not null then raise exception 'event_cancelled' using errcode = 'P0001'; end if;
    if v_event.ends_at <= (clock_timestamp() at time zone 'America/Argentina/Buenos_Aires') then raise exception 'event_ended' using errcode = 'P0001'; end if;
    select status into v_status from public.event_participations where event_id = p_event_id and user_id = v_user;
    if v_status = 'removed' then raise exception 'rejoin_requires_approval' using errcode = 'P0001'; end if;
    if v_status = 'confirmed' then return; end if;
    if (select count(*) from public.event_participations where event_id = p_event_id and status = 'confirmed') >= v_event.capacity then
        raise exception 'event_full' using errcode = 'P0001';
    end if;
    if v_status = 'cancelled' then
        update public.event_participations set status = 'confirmed' where event_id = p_event_id and user_id = v_user;
    else
        insert into public.event_participations(event_id, user_id, status) values (p_event_id, v_user, 'confirmed');
    end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.remove_event_image(p_event_id uuid, p_image_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
    perform planit_private.lock_gallery(p_event_id);
    delete from public.event_images where id = p_image_id and event_id = p_event_id;
    -- IDs remain stable. File metadata and physical object deliberately retained.
    set constraints public.event_images_event_id_sort_order_key deferred;
    with ordered as (select id, row_number() over(order by sort_order,id)-1 as position
        from public.event_images where event_id = p_event_id)
    update public.event_images i set sort_order = o.position from ordered o where i.id = o.id;
    set constraints public.event_images_event_id_sort_order_key immediate;
end;
$function$

CREATE OR REPLACE FUNCTION public.remove_participant(p_event_id uuid, p_participation_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
    v_event public.events%rowtype;
    v_status text;
begin
    if auth.uid() is null then raise exception 'authentication_required' using errcode = '42501'; end if;
    if current_setting('transaction_isolation') <> 'read committed' then
        raise exception 'retry_read_committed' using errcode = '40001';
    end if;
    select * into v_event from public.events where id = p_event_id for update;
    if not found or v_event.organizer_id <> auth.uid() then
        raise exception 'event_unavailable' using errcode = '42501';
    end if;
    if v_event.archived_at is not null or v_event.cancelled_at is not null
        or v_event.ends_at <= (clock_timestamp() at time zone 'America/Argentina/Buenos_Aires') then
        raise exception 'event_closed' using errcode = 'P0001';
    end if;
    select status into v_status from public.event_participations
        where id = p_participation_id and event_id = p_event_id for update;
    if not found then raise exception 'attendee_unavailable' using errcode = 'P0001'; end if;
    if v_status = 'removed' then return; end if;
    if v_status <> 'confirmed' then raise exception 'attendee_not_confirmed' using errcode = 'P0001'; end if;
    update public.event_participations set status = 'removed' where id = p_participation_id;
    -- Existing trigger records exactly one organizer_removal with auth.uid().
    -- Any trigger failure rolls back the transition and occupancy change.
end;
$function$

CREATE OR REPLACE FUNCTION public.reorder_event_images(p_event_id uuid, p_image_ids uuid[], p_expected_ids uuid[])
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_ids uuid[];
begin
    perform planit_private.lock_gallery(p_event_id);
    select coalesce(array_agg(id order by sort_order,id),'{}'::uuid[]) into v_ids from public.event_images where event_id = p_event_id;
    if p_expected_ids is distinct from v_ids then raise exception 'gallery_changed' using errcode = 'P0001'; end if;
    if p_image_ids is null or cardinality(p_image_ids) <> cardinality(v_ids)
        or exists(select 1 from unnest(p_image_ids) x where x is null or not x = any(v_ids))
        or (select count(distinct x) from unnest(p_image_ids) x) <> cardinality(v_ids) then
        raise exception 'invalid_image_order' using errcode = '23514';
    end if;
    set constraints public.event_images_event_id_sort_order_key deferred;
    update public.event_images i set sort_order = o.position-1
        from unnest(p_image_ids) with ordinality o(id,position) where i.id = o.id and i.event_id = p_event_id;
    set constraints public.event_images_event_id_sort_order_key immediate;
end;
$function$

CREATE OR REPLACE FUNCTION public.request_rejoin(p_event_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
    v_event public.events%rowtype;
    v_part public.event_participations%rowtype;
    v_request public.event_rejoin_requests%rowtype;
    v_now timestamp;
    v_id uuid;
begin
    if auth.uid() is null then raise exception 'authentication_required' using errcode = '42501'; end if;
    if current_setting('transaction_isolation') <> 'read committed' then raise exception 'retry_read_committed' using errcode = '40001'; end if;
    select * into v_event from public.events where id = p_event_id for update;
    if not found then raise exception 'event_unavailable' using errcode = '42501'; end if;
    if not planit_private.can_view_event(p_event_id) then raise exception 'event_unavailable' using errcode = '42501'; end if;
    select * into v_part from public.event_participations where event_id = p_event_id and user_id = auth.uid() for update;
    if not found or v_part.status <> 'removed' or v_event.organizer_id = auth.uid() then raise exception 'rejoin_not_removed' using errcode = 'P0001'; end if;
    v_now := clock_timestamp() at time zone 'America/Argentina/Buenos_Aires';
    if v_event.cancelled_at is not null or v_event.archived_at is not null or v_event.ends_at <= v_now then raise exception 'event_closed' using errcode = 'P0001'; end if;
    select * into v_request from public.event_rejoin_requests where participation_id = v_part.id order by requested_at desc, id desc limit 1 for update;
    if v_request.status = 'pending' then raise exception 'rejoin_already_pending' using errcode = 'P0001'; end if;
    if v_request.status = 'rejected' and v_request.resolved_at + interval '7 days' > v_now then raise exception 'rejoin_cooldown' using errcode = 'P0001'; end if;
    insert into public.event_rejoin_requests(participation_id, requested_at) values(v_part.id, v_now) returning id into v_id;
    return v_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.resolve_follow_request(p_follower_id uuid, p_request_version uuid, p_decision text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_follow public.user_follows%rowtype;
begin
    perform planit_private.lock_social_pair(p_follower_id);
    if p_decision is null or p_decision not in ('accepted', 'rejected') or p_request_version is null then
        raise exception 'invalid_follow_decision' using errcode = '22023';
    end if;
    if planit_private.social_blocked(p_follower_id) then
        raise exception 'request_unavailable' using errcode = '42501';
    end if;
    select * into v_follow from public.user_follows
        where follower_id = p_follower_id and followed_id = auth.uid();
    if not found or v_follow.request_version <> p_request_version then
        raise exception 'request_unavailable' using errcode = '42501';
    end if;
    if v_follow.status <> 'pending' then
        if v_follow.status = p_decision then return v_follow.status; end if;
        raise exception 'request_already_resolved' using errcode = '22023';
    end if;
    update public.user_follows set status = p_decision,
        responded_at = clock_timestamp() at time zone 'America/Argentina/Buenos_Aires'
        where follower_id = p_follower_id and followed_id = auth.uid();
    return p_decision;
end;
$function$

CREATE OR REPLACE FUNCTION public.resolve_rejoin(p_event_id uuid, p_request_id uuid, p_decision text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
    v_event public.events%rowtype;
    v_part public.event_participations%rowtype;
    v_request public.event_rejoin_requests%rowtype;
    v_now timestamp;
begin
    if auth.uid() is null then raise exception 'authentication_required' using errcode = '42501'; end if;
    if current_setting('transaction_isolation') <> 'read committed' then raise exception 'retry_read_committed' using errcode = '40001'; end if;
    select * into v_event from public.events where id = p_event_id for update;
    if not found or v_event.organizer_id <> auth.uid() then raise exception 'event_unavailable' using errcode = '42501'; end if;
    if p_decision is null or p_decision not in ('approved','rejected') then raise exception 'invalid_rejoin_decision' using errcode = '22023'; end if;
    select p.* into v_part from public.event_participations p join public.event_rejoin_requests r on r.participation_id = p.id
        where r.id = p_request_id and p.event_id = p_event_id for update of p;
    if not found then raise exception 'rejoin_unavailable' using errcode = 'P0001'; end if;
    select * into v_request from public.event_rejoin_requests where id = p_request_id for update;
    if v_request.status <> 'pending' then raise exception 'rejoin_already_resolved' using errcode = 'P0001'; end if;
    if v_part.status <> 'removed' then raise exception 'rejoin_not_removed' using errcode = 'P0001'; end if;
    v_now := clock_timestamp() at time zone 'America/Argentina/Buenos_Aires';
    if p_decision = 'approved' then
        if v_event.visibility = 'unlisted' and not exists (select 1 from public.event_access_grants g
            where g.event_id = p_event_id and g.user_id = v_part.user_id and g.status = 'active') then
            raise exception 'event_access_required' using errcode = '42501';
        end if;
        if v_event.cancelled_at is not null or v_event.archived_at is not null or v_event.ends_at <= v_now then raise exception 'event_closed' using errcode = 'P0001'; end if;
        if (select count(*) from public.event_participations where event_id=p_event_id and status='confirmed') >= v_event.capacity then raise exception 'event_full' using errcode = 'P0001'; end if;
        update public.event_participations set status='confirmed' where id=v_part.id;
    end if;
    -- Human-approved exception: rejection is allowed after closure; no transition is fabricated.
    update public.event_rejoin_requests set status=p_decision, resolved_at=v_now, reviewed_by=auth.uid() where id=p_request_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.restore_event_access(p_event_id uuid, p_user_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
    v_event public.events%rowtype;
    v_grant public.event_access_grants%rowtype;
    v_now timestamp;
begin
    if auth.uid() is null then raise exception 'access_denied' using errcode = '42501'; end if;
    select * into v_event from public.events where id = p_event_id for update;
    if not found or v_event.organizer_id <> auth.uid() then raise exception 'access_denied' using errcode = '42501'; end if;
    if v_event.visibility <> 'unlisted' then raise exception 'event_not_hidden'; end if;
    if v_event.cancelled_at is not null or v_event.archived_at is not null or
        v_event.ends_at <= clock_timestamp() at time zone 'America/Argentina/Buenos_Aires' then raise exception 'event_closed'; end if;
    -- Same lock order as revocation and all R3 participation operations.
    perform 1 from public.event_participations where event_id = p_event_id and user_id = p_user_id for update;
    select * into v_grant from public.event_access_grants where event_id = p_event_id and user_id = p_user_id for update;
    if not found then raise exception 'access_grant_missing'; end if;
    if v_grant.status = 'active' then return; end if;
    v_now := clock_timestamp() at time zone 'America/Argentina/Buenos_Aires';
    update public.event_access_grants set status = 'active', revoked_at = null, restored_at = v_now, updated_at = v_now where id = v_grant.id;
end;
$function$

CREATE OR REPLACE FUNCTION public.revoke_event_access(p_event_id uuid, p_user_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
    v_event public.events%rowtype;
    v_part public.event_participations%rowtype;
    v_grant public.event_access_grants%rowtype;
    v_now timestamp;
begin
    if auth.uid() is null then raise exception 'access_denied' using errcode = '42501'; end if;
    select * into v_event from public.events where id = p_event_id for update;
    if not found or v_event.organizer_id <> auth.uid() then raise exception 'access_denied' using errcode = '42501'; end if;
    if v_event.visibility <> 'unlisted' then raise exception 'event_not_hidden'; end if;
    if v_event.cancelled_at is not null or v_event.archived_at is not null or
        v_event.ends_at <= clock_timestamp() at time zone 'America/Argentina/Buenos_Aires' then raise exception 'event_closed'; end if;
    select * into v_part from public.event_participations where event_id = p_event_id and user_id = p_user_id for update;
    select * into v_grant from public.event_access_grants where event_id = p_event_id and user_id = p_user_id for update;
    if not found then raise exception 'access_grant_missing'; end if;
    if v_grant.status = 'revoked' then return; end if;
    if v_part.status = 'confirmed' then
        -- Existing trigger records exactly one organizer_removal; no manual history INSERT.
        update public.event_participations set status = 'removed' where id = v_part.id;
    end if;
    v_now := clock_timestamp() at time zone 'America/Argentina/Buenos_Aires';
    update public.event_access_grants set status = 'revoked', revoked_at = v_now, updated_at = v_now where id = v_grant.id;
end;
$function$

CREATE OR REPLACE FUNCTION public.rls_auto_enable()
 RETURNS event_trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
  cmd record;
  tbl name;
BEGIN
  FOR cmd IN
    SELECT *
    FROM pg_event_trigger_ddl_commands()
    WHERE command_tag IN ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO')
      AND object_type IN ('table','partitioned table')
  LOOP
     IF cmd.schema_name IS NOT NULL AND cmd.schema_name IN ('public') AND cmd.schema_name NOT IN ('pg_catalog','information_schema') AND cmd.schema_name NOT LIKE 'pg_toast%' AND cmd.schema_name NOT LIKE 'pg_temp%' THEN
      BEGIN
        SELECT c.relname INTO tbl FROM pg_catalog.pg_class c WHERE c.oid = cmd.objid;
        EXECUTE format('alter table if exists %I.%I enable row level security', cmd.schema_name, tbl);
        RAISE LOG 'rls_auto_enable: enabled RLS on %', cmd.object_identity;
      EXCEPTION
        WHEN OTHERS THEN
          RAISE LOG 'rls_auto_enable: failed to enable RLS on %', cmd.object_identity;
      END;
     ELSE
        RAISE LOG 'rls_auto_enable: skip % (either system schema or not in enforced list: %.)', cmd.object_identity, cmd.schema_name;
     END IF;
  END LOOP;
END;
$function$

CREATE OR REPLACE FUNCTION public.search_public_events(p_query text DEFAULT NULL::text, p_category_ids uuid[] DEFAULT NULL::uuid[], p_before_starts_at timestamp without time zone DEFAULT NULL::timestamp without time zone, p_before_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 30, p_south double precision DEFAULT NULL::double precision, p_north double precision DEFAULT NULL::double precision, p_west double precision DEFAULT NULL::double precision, p_east double precision DEFAULT NULL::double precision, p_date_from date DEFAULT NULL::date, p_date_to date DEFAULT NULL::date, p_origin_lat double precision DEFAULT NULL::double precision, p_origin_lng double precision DEFAULT NULL::double precision, p_radius_km double precision DEFAULT NULL::double precision)
 RETURNS TABLE(id uuid, organizer_id uuid, title text, description text, starts_at timestamp without time zone, ends_at timestamp without time zone, address text, location_name text, latitude double precision, longitude double precision, capacity integer, category_id uuid, visibility text, cancelled_at timestamp without time zone, archived_at timestamp without time zone, category_name text, image_path text)
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare
    c_earth_km constant double precision := 6371;
    v_query text := nullif(btrim(coalesce(p_query, '')), '');
    v_pattern text;
    v_categories uuid[] := case when coalesce(cardinality(p_category_ids), 0) = 0 then null else p_category_ids end;
    v_bounds integer := (p_south is not null)::integer + (p_north is not null)::integer
        + (p_west is not null)::integer + (p_east is not null)::integer;
    v_radius integer := (p_origin_lat is not null)::integer + (p_origin_lng is not null)::integer
        + (p_radius_km is not null)::integer;
    v_from timestamp;
    v_to_exclusive timestamp;
    v_angle double precision;
    v_dlat double precision;
    v_dlon double precision;
    v_lat_min double precision;
    v_lat_max double precision;
    v_lon_any boolean := true;
    v_lon_w double precision;
    v_lon_e double precision;
begin
    if (select auth.uid()) is null then
        return;
    end if;
    if v_query is not null and char_length(v_query) > 100 then
        raise exception 'search_query_too_long' using errcode = '22023';
    end if;
    if v_categories is not null and cardinality(v_categories) > 50 then
        raise exception 'search_too_many_categories' using errcode = '22023';
    end if;
    if (p_before_starts_at is null) <> (p_before_id is null) then
        raise exception 'search_invalid_cursor' using errcode = '22023';
    end if;
    if v_bounds not in (0, 4) or (v_bounds = 4 and not (
        p_south between -90 and 90 and p_north between p_south and 90
        and p_west between -180 and 180 and p_east between -180 and 180)) then
        raise exception 'search_invalid_bounds' using errcode = '22023';
    end if;

    -- Dates: "to" needs "from"; no inverted range; years kept in a sane window.
    if p_date_to is not null and p_date_from is null then
        raise exception 'search_invalid_dates' using errcode = '22023';
    end if;
    if p_date_from is not null then
        if p_date_from not between date '2000-01-01' and date '2100-12-31'
            or (p_date_to is not null and (p_date_to < p_date_from or p_date_to > date '2100-12-31')) then
            raise exception 'search_invalid_dates' using errcode = '22023';
        end if;
        v_from := p_date_from::timestamp;
        v_to_exclusive := (coalesce(p_date_to, p_date_from) + 1)::timestamp;
    end if;

    -- Radius: all-or-nothing, finite, > 0, bounded; origin on the globe.
    if v_radius not in (0, 3) or (v_radius = 3 and not (
        p_origin_lat between -90 and 90 and p_origin_lng between -180 and 180
        and p_radius_km > 0 and p_radius_km <= 20000)) then
        raise exception 'search_invalid_radius' using errcode = '22023';
    end if;
    if v_radius = 3 then
        v_angle := p_radius_km / c_earth_km;
        v_dlat := degrees(v_angle);
        v_lat_min := p_origin_lat - v_dlat * 1.001;
        v_lat_max := p_origin_lat + v_dlat * 1.001;
        -- Longitude window only when the circle stays clear of the poles and
        -- spans less than half the globe; otherwise latitude + Haversine decide.
        if v_lat_max < 90 and v_lat_min > -90 and v_angle < pi() / 2 then
            v_dlon := degrees(asin(least(1, sin(v_angle) / cos(radians(p_origin_lat))))) * 1.001;
            if v_dlon < 179 then
                v_lon_any := false;
                v_lon_w := p_origin_lng - v_dlon;
                v_lon_e := p_origin_lng + v_dlon;
                if v_lon_w < -180 then v_lon_w := v_lon_w + 360; end if;
                if v_lon_e > 180 then v_lon_e := v_lon_e - 360; end if;
            end if;
        end if;
    end if;

    if v_query is not null then
        v_pattern := '%' || replace(replace(replace(v_query, '\', '\\'), '%', '\%'), '_', '\_') || '%';
    end if;

    return query
    select e.id, e.organizer_id, e.title, e.description,
        e.starts_at, e.ends_at, e.address, e.location_name,
        e.latitude, e.longitude, e.capacity, e.category_id,
        e.visibility, e.cancelled_at, e.archived_at, c.name,
        (select f.storage_path
         from public.event_images i
         join public.files f on f.id = i.file_id
         where i.event_id = e.id
         order by i.sort_order
         limit 1)
    from public.events e
    join public.categories c on c.id = e.category_id
    where e.visibility = 'public'
        and e.cancelled_at is null
        and e.archived_at is null
        and e.ends_at > (statement_timestamp() at time zone 'America/Argentina/Buenos_Aires')
        and (v_pattern is null
            or e.title ilike v_pattern escape '\'
            or e.description ilike v_pattern escape '\')
        and (v_categories is null or (c.is_active and e.category_id = any(v_categories)))
        and (v_bounds = 0 or (
            e.latitude between p_south and p_north
            and case when p_west <= p_east then e.longitude between p_west and p_east
                     else e.longitude >= p_west or e.longitude <= p_east end))
        and (v_from is null or (e.starts_at >= v_from and e.starts_at < v_to_exclusive))
        and (v_radius = 0 or (
            e.latitude between v_lat_min and v_lat_max
            and (v_lon_any or case when v_lon_w <= v_lon_e then e.longitude between v_lon_w and v_lon_e
                                   else e.longitude >= v_lon_w or e.longitude <= v_lon_e end)
            and 2 * c_earth_km * asin(least(1, sqrt(
                power(sin(radians(e.latitude - p_origin_lat) / 2), 2)
                + cos(radians(p_origin_lat)) * cos(radians(e.latitude))
                * power(sin(radians(e.longitude - p_origin_lng) / 2), 2)))) <= p_radius_km))
        and (p_before_starts_at is null or (e.starts_at, e.id) > (p_before_starts_at, p_before_id))
    order by e.starts_at, e.id
    limit least(greatest(coalesce(p_limit, 30), 1), 100) + 1;
end;
$function$

CREATE OR REPLACE FUNCTION public.send_direct_message(p_conversation_id uuid, p_message_id uuid, p_body text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
    v_target uuid; v_existing public.messages%rowtype;
    v_body text := btrim(p_body, E' \t\n\r\f\v' || U&'\0085\00A0\1680\2000\2001\2002\2003\2004\2005\2006\2007\2008\2009\200A\2028\2029\202F\205F\3000\FEFF');
begin
    if auth.uid() is null then raise exception 'authentication_required' using errcode = '42501'; end if;
    select case when c.user_low_id = auth.uid() then c.user_high_id else c.user_low_id end
        into v_target from public.conversations c where c.id = p_conversation_id and c.kind = 'direct'
        and auth.uid() in (c.user_low_id, c.user_high_id);
    if not found then raise exception 'conversation_unavailable' using errcode = '42501'; end if;
    perform planit_private.lock_social_pair(v_target);
    if p_message_id is null or v_body is null or char_length(v_body) not between 1 and 2000 or v_body !~ '[^[:space:]]' then
        raise exception 'invalid_message' using errcode = '22023';
    end if;
    -- A successful retry is a read of an existing effect, also during a later block.
    select * into v_existing from public.messages where id = p_message_id;
    if found then
        if v_existing.sender_id = auth.uid() and v_existing.conversation_id = p_conversation_id
            and v_existing.body = v_body then return p_message_id; end if;
        raise exception 'message_id_conflict' using errcode = '22023';
    end if;
    if planit_private.social_blocked(v_target) then
        raise exception 'conversation_read_only' using errcode = '42501';
    end if;
    insert into public.messages(id, conversation_id, sender_id, body)
        values (p_message_id, p_conversation_id, auth.uid(), v_body);
    return p_message_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.send_event_chat_message(p_event_id uuid, p_message_id uuid, p_body text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
    v_event public.events%rowtype;
    v_conversation uuid;
    v_existing public.messages%rowtype;
    -- ASCII and Unicode whitespace (including non-breaking spaces) are not text.
    v_body text := btrim(p_body, E' \t\n\r\f\v' || U&'\0085\00A0\1680\2000\2001\2002\2003\2004\2005\2006\2007\2008\2009\200A\2028\2029\202F\205F\3000\FEFF');
begin
    if auth.uid() is null then raise exception 'authentication_required' using errcode = '42501'; end if;
    if current_setting('transaction_isolation') <> 'read committed' then raise exception 'retry_read_committed' using errcode = '40001'; end if;
    if p_message_id is null or v_body is null or char_length(v_body) not between 1 and 2000 or v_body !~ '[^[:space:]]' then
        raise exception 'invalid_message';
    end if;
    -- Same lock order as register/leave; locks state updates until send finishes.
    select * into v_event from public.events where id = p_event_id for update;
    if not found then raise exception 'chat_unavailable' using errcode = '42501'; end if;
    -- Lock membership too, including future removal operations that update its row.
    if v_event.organizer_id <> auth.uid() then
        perform 1 from public.event_participations where event_id = p_event_id and user_id = auth.uid() and status = 'confirmed' for update;
        if not found then raise exception 'chat_unavailable' using errcode = '42501'; end if;
    end if;
    if not planit_private.can_read_event_chat(p_event_id) then raise exception 'chat_unavailable' using errcode = '42501'; end if;
    select id into v_conversation from public.conversations where event_id = p_event_id;
    select * into v_existing from public.messages where id = p_message_id;
    if found then
        if v_existing.sender_id = auth.uid() and v_existing.conversation_id = v_conversation and v_existing.body = v_body then return v_existing.id; end if;
        raise exception 'message_id_conflict';
    end if;
    if v_event.cancelled_at is not null or v_event.archived_at is not null
        or v_event.ends_at <= (clock_timestamp() at time zone 'America/Argentina/Buenos_Aires') then raise exception 'chat_read_only'; end if;
    insert into public.messages(id, conversation_id, sender_id, body) values (p_message_id, v_conversation, auth.uid(), v_body);
    return p_message_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.set_event_visibility(p_event_id uuid, p_visibility text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_event public.events%rowtype;
begin
    if auth.uid() is null then raise exception 'authentication_required' using errcode = '42501'; end if;
    if current_setting('transaction_isolation') <> 'read committed' then raise exception 'retry_read_committed' using errcode = '40001'; end if;
    if p_visibility is null or p_visibility not in ('public','unlisted') then raise exception 'invalid_visibility' using errcode = '23514'; end if;
    select * into v_event from public.events where id = p_event_id for update;
    if not found or v_event.organizer_id <> auth.uid() then raise exception 'event_unavailable' using errcode = '42501'; end if;
    if v_event.cancelled_at is not null or v_event.archived_at is not null
        or v_event.starts_at <= (clock_timestamp() at time zone 'America/Argentina/Buenos_Aires') then
        raise exception 'event_not_editable' using errcode = 'P0001';
    end if;
    if v_event.visibility <> p_visibility then update public.events set visibility = p_visibility where id = p_event_id; end if;
    return p_event_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.set_my_avatar(p_storage_path text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_file uuid; v_mime text; v_size bigint;
begin
    if auth.uid() is null then raise exception 'authentication_required' using errcode = '42501'; end if;
    if current_setting('transaction_isolation') <> 'read committed' then
        raise exception 'retry_read_committed' using errcode = '40001';
    end if;
    perform 1 from public.profiles where id = auth.uid() for no key update;
    if not found then raise exception 'profile_unavailable' using errcode = '42501'; end if;
    if p_storage_path is null then
        update public.profiles set avatar_file_id = null where id = auth.uid(); return null;
    end if;
    if split_part(p_storage_path,'/',1) <> auth.uid()::text then
        raise exception 'invalid_avatar' using errcode = '42501';
    end if;
    perform pg_advisory_xact_lock(hashtextextended('avatars/' || p_storage_path,0));
    select metadata->>'mimetype',(metadata->>'size')::bigint into v_mime,v_size
        from storage.objects where bucket_id = 'avatars' and name = p_storage_path and owner_id = auth.uid()::text
            and metadata ->> 'cacheControl' in ('no-store','no-cache','max-age=0');
    if not found then raise exception 'invalid_avatar' using errcode = '42501'; end if;
    insert into public.files(uploaded_by,bucket_name,storage_path,mime_type,size_bytes)
        values (auth.uid(),'avatars',p_storage_path,v_mime,v_size)
        on conflict (bucket_name,storage_path) do nothing;
    select id into v_file from public.files where bucket_name = 'avatars' and storage_path = p_storage_path and uploaded_by = auth.uid();
    if v_file is null then raise exception 'invalid_avatar' using errcode = '42501'; end if;
    update public.profiles set avatar_file_id = v_file where id = auth.uid();
    return v_file;
end;
$function$

CREATE OR REPLACE FUNCTION public.set_my_category_interests(p_category_ids uuid[])
 RETURNS TABLE(category_id uuid)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
    v_user_id uuid := auth.uid();
begin
    if v_user_id is null then
        raise exception 'interests_auth_required' using errcode = '42501';
    end if;
    if p_category_ids is null or array_position(p_category_ids, null) is not null
       or cardinality(p_category_ids) <> (select count(distinct id) from unnest(p_category_ids) as ids(id)) then
        raise exception 'interests_invalid_selection' using errcode = '22023';
    end if;

    -- Serialize even an initially empty selection. Lock order: own profile,
    -- then categories ordered by id. Keep category validation stable until ACK.
    perform 1 from public.profiles where id = v_user_id for update;
    if not found then
        raise exception 'interests_profile_required' using errcode = '42501';
    end if;
    perform 1 from public.categories c where c.id = any(p_category_ids)
        order by c.id for share;
    if exists (
        select 1 from unnest(p_category_ids) as ids(id)
        left join public.categories c on c.id = ids.id
        where c.id is null or (not c.is_active and not exists (
            select 1 from public.user_category_interests i
            where i.user_id = v_user_id and i.category_id = ids.id
        ))
    ) then
        raise exception 'interests_category_unavailable' using errcode = '22023';
    end if;

    delete from public.user_category_interests i
        where i.user_id = v_user_id and not (i.category_id = any(p_category_ids));
    insert into public.user_category_interests (user_id, category_id)
        select v_user_id, ids.id from unnest(p_category_ids) as ids(id)
        on conflict on constraint user_category_interests_pkey do nothing;
    return query select i.category_id from public.user_category_interests i
        where i.user_id = v_user_id order by i.category_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.update_event(p_event_id uuid, p_title text, p_description text, p_starts_at timestamp without time zone, p_ends_at timestamp without time zone, p_category_id uuid, p_capacity integer, p_address text, p_latitude double precision, p_longitude double precision, p_location_name text DEFAULT NULL::text, p_visibility text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
    v_user uuid := auth.uid();
    v_event public.events%rowtype;
    v_now timestamp;
begin
    if v_user is null then raise exception 'authentication_required' using errcode = '42501'; end if;
    if current_setting('transaction_isolation') <> 'read committed' then
        raise exception 'retry_read_committed' using errcode = '40001';
    end if;
    if p_visibility is not null and p_visibility not in ('public','unlisted') then raise exception 'invalid_visibility' using errcode = '23514'; end if;
    -- Same lock as registration/leave. Count AFTER lock using a fresh snapshot.
    select * into v_event from public.events where id = p_event_id for update;
    if not found then raise exception 'event_unavailable' using errcode = '42501'; end if;
    if v_event.organizer_id <> v_user then raise exception 'not_event_organizer' using errcode = '42501'; end if;
    v_now := clock_timestamp() at time zone 'America/Argentina/Buenos_Aires';
    if v_event.cancelled_at is not null or v_event.archived_at is not null or v_event.starts_at <= v_now then
        raise exception 'event_not_editable' using errcode = 'P0001';
    end if;
    if p_starts_at is null or p_ends_at is null or not isfinite(p_starts_at) or not isfinite(p_ends_at)
        or p_starts_at <= v_now then raise exception 'start_not_future' using errcode = 'P0001'; end if;
    if p_ends_at <= p_starts_at then raise exception 'end_before_start' using errcode = 'P0001'; end if;
    if not exists (select 1 from public.categories where id = p_category_id and is_active) then
        raise exception 'category_inactive' using errcode = 'P0001';
    end if;
    if p_capacity is null or p_capacity < 1 then raise exception 'invalid_capacity' using errcode = '23514'; end if;
    if p_capacity < (select count(*) from public.event_participations where event_id = p_event_id and status = 'confirmed') then
        raise exception 'capacity_below_confirmed' using errcode = 'P0001';
    end if;
    -- Existing NOT NULL/CHECK/FK constraints validate remaining content atomically.
    update public.events set title = btrim(p_title), description = btrim(p_description),
        starts_at = p_starts_at, ends_at = p_ends_at, category_id = p_category_id,
        capacity = p_capacity, address = btrim(p_address), latitude = p_latitude,
        longitude = p_longitude, location_name = nullif(btrim(p_location_name), ''), visibility = coalesce(p_visibility, v_event.visibility)
    where id = p_event_id;
    return p_event_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.update_my_social_profile(p_username text, p_display_name text, p_first_name text, p_last_name text, p_birth_date date, p_sex text, p_bio text, p_visibility text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_old_visibility text; v_accepted integer := 0;
begin
    if auth.uid() is null then raise exception 'authentication_required' using errcode = '42501'; end if;
    if current_setting('transaction_isolation') <> 'read committed' then
        raise exception 'retry_read_committed' using errcode = '40001';
    end if;
    select visibility into v_old_visibility from public.profiles
        where id = auth.uid() for no key update;
    if not found then raise exception 'profile_unavailable' using errcode = '42501'; end if;
    update public.profiles set username = p_username, display_name = p_display_name,
        first_name = p_first_name, last_name = p_last_name, birth_date = p_birth_date,
        sex = p_sex, bio = p_bio, visibility = p_visibility where id = auth.uid();
    if v_old_visibility = 'private' and p_visibility = 'public' then
        update public.user_follows f set status = 'accepted',
            responded_at = clock_timestamp() at time zone 'America/Argentina/Buenos_Aires'
        where f.followed_id = auth.uid() and f.status = 'pending'
            and not planit_private.social_blocked(f.follower_id);
        get diagnostics v_accepted = row_count;
    end if;
    return jsonb_build_object('visibility', p_visibility, 'accepted_requests', v_accepted);
end;
$function$
